package com.rpb.reservation.workforce.attendance.daily;
import static com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.*;import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.attendancepolicy.*;import com.rpb.reservation.workforce.approval.*;import com.rpb.reservation.workforce.persistence.*;import com.rpb.reservation.workforce.scheduling.*;import com.rpb.reservation.workforce.leave.*;import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class AttendanceExceptionService {
 private final WorkforceAccess gate;private final WorkforceEmployeeRepository employees;private final SchedulingRepository schedules;private final AttendancePolicyRepository policies;private final AttendanceDailyRepository repository;private final LeaveTypeRepository types;private final ApprovalRepository approvals;private final WorkforceAudit audit;private final Clock clock;
 public AttendanceExceptionService(WorkforceAccess gate,WorkforceEmployeeRepository employees,SchedulingRepository schedules,AttendancePolicyRepository policies,AttendanceDailyRepository repository,LeaveTypeRepository types,ApprovalRepository approvals,WorkforceAudit audit,Clock clock){this(gate,employees,schedules,policies,repository,types,approvals,audit,clock,null);}
 @org.springframework.beans.factory.annotation.Autowired
 public AttendanceExceptionService(WorkforceAccess gate,WorkforceEmployeeRepository employees,SchedulingRepository schedules,AttendancePolicyRepository policies,AttendanceDailyRepository repository,LeaveTypeRepository types,ApprovalRepository approvals,WorkforceAudit audit,Clock clock,com.rpb.reservation.workforce.leave.account.IntervalLeaveAccountBridge leaveBalances){this.leaveBalances=leaveBalances;this.gate=gate;this.employees=employees;this.schedules=schedules;this.policies=policies;this.repository=repository;this.types=types;this.approvals=approvals;this.audit=audit;this.clock=clock;}
 private final com.rpb.reservation.workforce.leave.account.IntervalLeaveAccountBridge leaveBalances;
 private void scoped(CurrentActor actor,UUID store,UUID employee,LocalDate date){gate.enter(actor,store);if(!schedules.hasStoreAssignment(actor.tenantId(),employee,store))throw WorkforceException.missing();if(!gate.managedStores(actor).contains(store)&&!employees.byAccount(actor.tenantId(),actor.actorId()).orElseThrow(WorkforceException::forbidden).id().equals(employee))throw WorkforceException.forbidden();}
 public List<IntervalException> list(CurrentActor actor,UUID store,LocalDate from,LocalDate to,UUID employee){gate.enter(actor,store);if(from==null||to==null||to.isBefore(from)||to.isAfter(from.plusDays(62)))throw WorkforceException.invalid();boolean manager=gate.managedStores(actor).contains(store);UUID self=manager?null:employees.byAccount(actor.tenantId(),actor.actorId()).orElseThrow(WorkforceException::forbidden).id();if(self!=null&&employee!=null&&!self.equals(employee))throw WorkforceException.forbidden();var company=policies.store(actor.tenantId(),store).companyId();var result=new ArrayList<IntervalException>();for(var e:repository.employees(actor.tenantId(),store,from,to)){if(employee!=null&&!employee.equals(e)||self!=null&&!self.equals(e))continue;result.addAll(repository.exceptions(actor.tenantId(),company,e,from,to).stream().filter(x->store.equals(x.storeId())).toList());}if(result.size()>2000)throw WorkforceException.invalid();return result;}
 @Transactional public IntervalException submit(CurrentActor actor,UUID store,UUID id,ExceptionWrite c){gate.sourceWrite(actor);gate.enter(actor,store);if(id==null||c==null||c.employeeId()==null||c.companyId()==null||c.workDate()==null||!Set.of("leave","absence","extra_work").contains(c.kind()==null?"":c.kind())||c.startAt()==null||c.endAt()==null||!c.endAt().isAfter(c.startAt())||Duration.between(c.startAt(),c.endAt()).compareTo(Duration.ofDays(2))>0||c.reason()==null||c.reason().isBlank()||c.reason().trim().length()>500||(c.kind().equals("leave")?c.typeId()==null:c.typeId()!=null))throw WorkforceException.invalid();if(c.medicalReference()!=null&&(!c.kind().equals("leave")||c.medicalReference().isBlank()||c.medicalReference().trim().length()>500))throw WorkforceException.invalid();scoped(actor,store,c.employeeId(),c.workDate());schedules.lock("workforce.attendance-exception:"+actor.tenantId()+":"+id);employees.lock(c.employeeId());c=new ExceptionWrite(c.employeeId(),c.companyId(),c.workDate(),c.kind(),c.typeId(),c.startAt().truncatedTo(ChronoUnit.MICROS),c.endAt().truncatedTo(ChronoUnit.MICROS),c.reason().trim(),c.medicalReference()==null?null:c.medicalReference().trim());var old=repository.exception(actor.tenantId(),id).orElse(null);if(old!=null){if(store.equals(old.storeId())&&actor.actorId().equals(old.applicantId())&&new ExceptionWrite(old.employeeId(),old.companyId(),old.workDate(),old.kind(),old.typeId(),old.startAt(),old.endAt(),old.reason(),old.medicalReference()).equals(c))return old;throw WorkforceException.conflict();}if(!schedules.assigned(actor.tenantId(),c.employeeId(),store,c.workDate())||!policies.company(actor.tenantId(),c.employeeId(),c.workDate()).equals(c.companyId())||!policies.store(actor.tenantId(),store).companyId().equals(c.companyId()))throw WorkforceException.invalid();var zone=ZoneId.of(schedules.timezone(actor.tenantId(),store));validateAttribution(actor.tenantId(),c,zone);if(repository.overlaps(actor.tenantId(),c.employeeId(),id,c.startAt(),c.endAt()))throw new WorkforceException("WORKFORCE_EXCEPTION_OVERLAP",409);String name=null;boolean paid=false;if(c.kind().equals("leave")){schedules.lock("workforce.leave-type:"+c.typeId());var type=types.find(actor.tenantId(),store,c.typeId()).orElseThrow(WorkforceException::missing);if(!type.enabled())throw WorkforceException.invalid();name=type.name();paid=type.paid();}var next=new IntervalException(id,c.employeeId(),c.companyId(),store,c.workDate(),c.kind(),c.typeId(),name,paid,c.startAt(),c.endAt(),c.reason(),"pending",actor.actorId(),null,null,null,1,clock.instant().truncatedTo(ChronoUnit.MICROS),c.medicalReference());if(leaveBalances!=null)leaveBalances.reserve(actor,next);repository.create(actor.tenantId(),next);audit.changed(actor,store,"attendance-exception.submit",id,null,next);return next;}
 @Transactional public IntervalException decide(CurrentActor actor,UUID store,UUID id,DecisionWrite c){gate.sourceWrite(actor);gate.enter(actor,store);if(c==null||c.expectedVersion()==null||c.expectedVersion()<1||!Set.of("approved","rejected","withdrawn","cancel_requested","cancelled","cancel_rejected").contains(c.status()==null?"":c.status())||c.note()==null||c.note().trim().length()>500||(!c.status().equals("withdrawn")&&c.note().isBlank()))throw WorkforceException.invalid();var initial=repository.exception(actor.tenantId(),id).orElseThrow(WorkforceException::missing);if(!store.equals(initial.storeId()))throw WorkforceException.missing();scoped(actor,store,initial.employeeId(),initial.workDate());employees.lock(initial.employeeId());var old=repository.exception(actor.tenantId(),id).orElseThrow();var employee=employees.find(actor.tenantId(),old.employeeId()).orElseThrow();boolean personal=Set.of("withdrawn","cancel_requested").contains(c.status());if(personal){if(!actor.actorId().equals(old.applicantId()))throw WorkforceException.forbidden();}else {var block=ApprovalReviewerPolicy.block(gate.isHeadOffice(actor),gate.managedStores(actor).contains(store),actor.actorId(),employee.accountId(),approvals.managerAccount(actor.tenantId(),employee.accountId()));if(block!=null)throw new WorkforceException(block,403);if(actor.actorId().equals(old.applicantId()))throw new WorkforceException("WORKFORCE_SELF_REVIEW",403);}String target=c.status().equals("cancel_rejected")?"approved":c.status();String note=c.note().trim();if(old.version()==c.expectedVersion()+1&&old.status().equals(target)&&c.status().equals(old.lastAction())&&actor.actorId().equals(old.reviewerId())&&note.equals(old.reviewNote()))return old;if(old.version()!=c.expectedVersion())throw WorkforceException.conflict();boolean allowed=switch(c.status()){case "approved","rejected","withdrawn"->old.status().equals("pending");case "cancel_requested"->old.status().equals("approved");case "cancelled","cancel_rejected"->old.status().equals("cancel_requested");default->false;};if(!allowed)throw WorkforceException.conflict();if(c.status().equals("approved")&&repository.overlaps(actor.tenantId(),old.employeeId(),id,old.startAt(),old.endAt()))throw new WorkforceException("WORKFORCE_EXCEPTION_OVERLAP",409);if(leaveBalances!=null)leaveBalances.decision(actor,old,c.status());repository.decide(actor.tenantId(),id,target,c.status(),actor.actorId(),note,old.version()+1);var saved=repository.exception(actor.tenantId(),id).orElseThrow();audit.changed(actor,store,"attendance-exception."+c.status(),id,old,saved);return saved;}
 private void validateAttribution(UUID tenant,ExceptionWrite c,ZoneId fallback){var windows=new ArrayList<AttendanceExceptionAttribution.Window>();var assignments=policies.assignments(tenant,c.employeeId());var ownPolicy=assignments.stream().filter(p->!p.effectiveFrom().isAfter(c.workDate())&&c.companyId().equals(p.companyId())).max(Comparator.comparing(AttendancePolicyDtos.PolicyVersion::effectiveFrom)).orElse(null);ZoneId attributionZone=ownPolicy!=null&&ownPolicy.timezone()!=null?ZoneId.of(ownPolicy.timezone()):fallback;for(int offset=-1;offset<=1;offset++){var date=c.workDate().plusDays(offset);var ids=approvals.bounded(approvals.scheduleIds(tenant,null,c.companyId(),date,date,c.employeeId()));var rows=schedules.scoped(tenant,ids).stream().filter(x->x.schedule().status().equals("scheduled")&&!schedules.deleted(tenant,x.schedule().id())).toList();if(!rows.isEmpty()){if(offset==0&&ownPolicy==null){var zones=rows.stream().map(x->x.schedule().timezone()).distinct().toList();if(zones.size()!=1)throw WorkforceException.invalid();attributionZone=ZoneId.of(zones.getFirst());}for(var row:rows)windows.add(new AttendanceExceptionAttribution.Window(date,row.schedule().startAt(),row.schedule().endAt()));continue;}var policy=assignments.stream().filter(p->!p.effectiveFrom().isAfter(date)&&c.companyId().equals(p.companyId())).max(Comparator.comparing(AttendancePolicyDtos.PolicyVersion::effectiveFrom)).orElse(null);if(policy==null||policy.arrangement()==null||!policy.arrangement().weekdays().contains(date.getDayOfWeek().getValue()))continue;var zone=policy.timezone()==null?fallback:ZoneId.of(policy.timezone());var start=date.atTime(policy.arrangement().startTime()).atZone(zone).toInstant();windows.add(new AttendanceExceptionAttribution.Window(date,start,start.plusSeconds((policy.arrangement().standardWorkMinutes()+policy.arrangement().unpaidBreakMinutes())*60L)));}AttendanceExceptionAttribution.validate(c,attributionZone,windows);}
}
